-- products 800-880
insert into public.products (
  sku, name, brand_id, category_id, category_path, description,
  price_cents, compare_at_price_cents, stock, cover_path, metadata
)
select
  x->>'sku',
  x->>'name',
  b.id,
  c.id,
  coalesce(array(select jsonb_array_elements_text(x->'category_path')), '{}'),
  coalesce(x->>'description', ''),
  coalesce((x->>'price_cents')::int, 0),
  nullif(x->>'compare_at_price_cents', '')::int,
  coalesce((x->>'stock')::int, 0),
  nullif(x->>'cover_path', ''),
  jsonb_build_object('source', 'cabesto-catalog')
from jsonb_array_elements($json$[{"sku":"PCPL-1116","name":"1ER ETAGE MK25 EVO SCUBAPRO","brand":"SCUBAPRO","category_path":["plongee","plongee-sous-marine","detendeurs-et-octopus"],"description":"1ER ETAGE MK25 EVO SCUBAPROLe premier étage de Scubapro MK25 évolue en 2015 vers l'EVO... nouveaux brevets, nouveau système d'isolation, un premier étage de détendeur de plongée haut de gamme et ultra performant !• Le nouveau XTIS (Système d’isolation thermique étendu), équipé d’un mécanisme complètement isolé de l’environnement, améliore la résistance à l’eau froide/au givrage sans compromis sur la performance respiratoire du piston (brevet en cours).• Des ailettes supplémentaires situées sur le corps usiné augmentent les échanges thermiques.• Un design moderne.• Les composants essentiels du système d’isolation sont en bleu.• Conforme aux exigences de la norme EN 250-2014.• Piston compensé• 2 Sorties haute pression• 5 Sorties pression intermédiaire haut débit HFP• Tourelle pivotanteCe détendeur a été fabriqué conformément aux exigences du règlement CE 2016/425 pour les EPI (catégorie 3) suivant la norme NF EN 250.","price_cents":43999,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/PCPL-1116/01-mk25-evo.jpg"},{"sku":"PCPL-1121","name":"SANDOWS 16 MM LA PAIRE DESSAULT","brand":"DESSAULT","category_path":["plongee","chasse-sous-marine","arbaletes-et-fusils-harpons"],"description":"Le savoir-faire Dessault allié à la qualité des produits utilisés, procure à nos sandows un module d'élasticité bien supérieur aux autres types de latex naturels ou synthétiques. La production en fil continu préserve les chaînes moléculaires du latex. Associée à une maîtrise parfaite du séchage, cette technique permet d'atteindre exactement la nervosité et la longévité recherchée. Réputée efficace et robuste, la gomme Dessault a séduit de nombreux chasseurs à travers toutes les mers. Caractéristiques techniques - Fabrication française depuis 20 ans- Gomme noire diamètre 16 mm- Pure sève d'hévéa de Malaisie, 100% naturelle- Séchage lent et nature- Vulcanisation continue- Testés individuellement","price_cents":1099,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/PCPL-1121/01-sandows-viss_s_11_1.jpg"},{"sku":"PCPL-1122","name":"SANDOW CIRCULAIRE Ø 16 MM DESSAULT","brand":"DESSAULT","category_path":["plongee","chasse-sous-marine","arbaletes-et-fusils-harpons"],"description":"Le savoir-faire Dessault allié à la qualité des produits utilisés, procure à nos sandows un module d'élasticité bien supérieur aux autres types de latex naturels ou synthétiques. La production en fil continu préserve les chaînes moléculaires du latex. Associée à une maîtrise parfaite du séchage, cette technique permet d'atteindre exactement la nervosité et la longévité recherchée. Réputée efficace et robuste, la gomme Dessault a séduit de nombreux chasseurs à travers toutes les mers. Caractéristiques techniques - Fabrication française depuis 20 ans- Gomme noire diamètre 16 mm- Pure sève d'hévéa de Malaisie, 100% naturelle- Séchage lent et nature- Vulcanisation continue- Testés individuellement","price_cents":999,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/PCPL-1122/01-sandow-16_3.jpg"},{"sku":"PCPL-1226","name":"SANDOW BAGUE NOIR LATEX 17-18 MM","brand":"SALVIMAR","category_path":["plongee","chasse-sous-marine","arbaletes-et-fusils-harpons"],"description":"Pour un tir efficace, il faut trouver la proportion équilibrée entre l’élasticité des sandows et la masse de la flèche","price_cents":2499,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/PCPL-1226/01-pcpl-1226-pl-9128-picture_1-pcpl-1226-1.jpg"},{"sku":"PCPL-1228","name":"SANDOW CIRCULAIRE NOIR LATEX 17-18 MM","brand":"SALVIMAR","category_path":["plongee"],"description":"Pour un tir efficace, il faut trouver la proportion équilibrée entre l’élasticité des sandows et la masse de la flèche.","price_cents":2039,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/PCPL-1228/0